issue_context.body:
codegen fails for these examples:

``` csharp
    public class CodeGenFail1<T>
    {
        //can be any access modifier
        public Nested nested;
        //can be public or internal or internal protected.
        public class Nested {}
    }

    public class CodeGenFail2
    {
        //can be any access modifier
        public Nested<int> nested;
        //can be public or internal or internal protected.
        public class Nested<T> {}
    }

    public interface IFail : IGrain
    {
        Task Do(CodeGenFail1<int> t);
        Task Do(CodeGenFail2 t);
    }
```

comments:
Currently Orleans explicitly doesn't support the serialization of nested classes. I never looked into it, but I followed suit when creating the code generator in #528, so that bug is also present in the Roslyn codegen.

Here's a test case, just in case we want to fix this.

``` c#
public class NestedGeneric<T>
{
  public Nested Payload { get; set; }

  public class Nested
  {
    public T Value { get; set; }
  }
}

public class NestedConstructedGeneric
{
  public Nested<int> Payload { get; set; }

  public class Nested<T>
  {
    public T Value { get; set; }
  }
}

public interface IFail : IGrainWithGuidKey
{
  Task<int> Do(NestedGeneric<int> value);
  Task<int> Do(NestedConstructedGeneric value);
}

/// <summary>
/// Tests that nested classes do not fail code generation.
/// </summary>
public class FailGrain : Grain,  IFail
{
  public Task<int> Do(NestedGeneric<int> value)
  {
    return Task.FromResult(value.Payload.Value);
  }

  public Task<int> Do(NestedConstructedGeneric value)
  {
    return Task.FromResult(value.Payload.Value);
  }
}

[TestMethod, TestCategory("BVT"), TestCategory("Functional"), TestCategory("CodeGen")]
public async Task RuntimeCodeGenNestedGenericTest()
{
  const int Expected = 123985;
  var grain = this.GrainFactory.GetGrain<IFail>(Guid.NewGuid());

  var nestedGeneric = new NestedGeneric<int> { Payload = new NestedGeneric<int>.Nested { Value = Expected } };
  var actual = await grain.Do(nestedGeneric);
  Assert.AreEqual(Expected, actual, "NestedGeneric<int>.Nested value should round-trip correctly.");

  var nestedConstructedGeneric = new NestedConstructedGeneric
  {
    Payload = new NestedConstructedGeneric.Nested<int> { Value = Expected }
  };
  actual = await grain.Do(nestedConstructedGeneric);
  Assert.AreEqual(Expected, actual, "NestedConstructedGeneric.Nested<int> value should round-trip correctly.");
}
```
